    <script>
        document.addEventListener('DOMContentLoaded', function() {
            // 宝贝的这个函数依然是核心，妈妈保留了它的所有优点！
            function renderSection(container, rawContent) {
                if (!container) return;
                if (!rawContent || rawContent.trim() === '') {
                    container.style.display = 'none';
                    return;
                }

                const body = container.querySelector('.section-body');
                const articleRegex = /<(\d+)>[\s\n]*\[标题\s*[:：]\s*([^\]]*)\][\s\n]*\[内容\s*[:：]([\s\S]*?)\][\s\n]*<\/\1>/g;
                let match;
                let hasContent = false;

                while ((match = articleRegex.exec(rawContent)) !== null) {
                    hasContent = true;
                    const title = match[2].trim();
                    const content = match[3].trim();

                    if (title || content) {
                        const articleDiv = document.createElement('div');
                        articleDiv.className = 'article';
                        let articleHTML = '';
                        if (title) {
                            articleHTML += `<h3 class="article-title">${title}</h3>`;
                        }
                        if (content) {
                            articleHTML += `<p class="article-content">${content.replace(/\n/g, '<br>')}</p>`;
                        }
                        articleDiv.innerHTML = articleHTML;
                        body.appendChild(articleDiv);
                    }
                }
                if (!hasContent) {
                    container.style.display = 'none';
                }
            }

            // 渲染正面内容
            renderSection(document.getElementById('headlines'), `$2`);
            renderSection(document.getElementById('current-affairs'), `$3`);
            renderSection(document.getElementById('regional-news'), `$4`);
            renderSection(document.getElementById('official-releases'), `$5`);

            // 渲染反面内容
            renderSection(document.getElementById('opinions'), `$6`);
            renderSection(document.getElementById('economy'), `$7`);
            renderSection(document.getElementById('life'), `$8`);
            renderSection(document.getElementById('commissions'), `$9`);

            // --- 翻转和高度适应的核心魔法在这里！ ---
            const flipper = document.querySelector('.newspaper-flipper');
            const frontPage = document.querySelector('.front');
            const backPage = document.querySelector('.back');

            // 确保内容渲染完成后再计算高度
            setTimeout(() => {
                const frontHeight = frontPage.scrollHeight;
                const backHeight = backPage.scrollHeight;

                // 初始高度设为正面的高度
                flipper.style.height = frontHeight + 'px';

                flipper.addEventListener('click', function() {
                    this.classList.toggle('flipped');

                    // 根据翻转状态，平滑地改变容器高度
                    if (this.classList.contains('flipped')) {
                        flipper.style.height = backHeight + 'px';
                    } else {
                        flipper.style.height = frontHeight + 'px';
                    }
                });
            }, 100); // 延迟一点点确保DOM完全渲染
        });
    </script>
</body>
</html>
