    function parseFighters(data, team) {
      const fighters = [];
      // --- 修改开始: 改进正则表达式以提高容错性 ---
      // 原正则: /<战斗员\d+>[\s\n]*\[姓名:([^\]]*)\][\s\n]*\[HP:([^\]]*)\][\s\n]*\[位置:([^\]]*)\][\s\n]*\[当前姿态:([^\]]*)\][\s\n]*\[图示:([^\]]*)\][\s\n]*\[语言:([^\]]*)\][\s\n]*\[所有姿态:([^\]]*)\][\s\n]*<\/战斗员\d+>/g;
      // 修改后正则: 允许全/半角冒号，允许冒号后和方括号前有空格，并对捕获的图示关键字去除前后空格
      const regex = /<战斗员\d+>[\s\n]*\[姓名:([^\]]*)\][\s\n]*\[HP:([^\]]*)\][\s\n]*\[位置:([^\]]*)\][\s\n]*\[当前姿态:([^\]]*)\][\s\n]*\[图示[:：]\s*([^\]]*?)\s*\][\s\n]*\[语言:([^\]]*)\][\s\n]*\[所有姿态:([^\]]*)\][\s\n]*<\/战斗员\d+>/g;
      // --- 修改结束 ---
      let match;
      let index = 0;
      while ((match = regex.exec(data)) !== null) {
        fighters.push({
          id: `${team}-${index++}`,
          name: match[1].trim(), // 对捕获内容进行trim
          hp: match[2].trim(),
          position: match[3].trim(),
          currentStance: match[4].trim(),
          imageKeyword: match[5].trim(), // 对捕获的图示关键字进行trim
          speech: match[6].trim(),
          allStances: match[7].split(/\s+/).filter(s => s.trim() !== '')
        });
      }
      return fighters;
    }

    function initBattleBoard(team, fighters) {
      const board = document.getElementById(`team-${team}-board`);
      board.innerHTML = '';
      const positionMap = team === 'a' ?
        { '后': 0, '中': 1, '前': 2 } : // A方: 后->0, 中->1, 前->2
        { '前': 0, '中': 1, '后': 2 }; // B方: 前->0, 中->1, 后->2 (B方棋盘视觉上是反的)

      for (let i = 0; i < 9; i++) {
        const cell = document.createElement('div');
        const row = Math.floor(i / 3);
        const col = i % 3;
        cell.className = `battle-cell team-${team}`;
        cell.dataset.row = row;
        cell.dataset.col = col;
        board.appendChild(cell);
      }

      fighters.forEach(fighter => {
          const posMatch = fighter.position.match(/(前|中|后)(\d)/);
          if (!posMatch) {
              console.warn(`Invalid position format for fighter ${fighter.name}: ${fighter.position}. Expected format like '前1', '中2', '后3'.`);
              return; // 跳过格式无效的战士
          }
          const [, pos, num] = posMatch;
          const col = positionMap[pos];
          const row = parseInt(num) - 1;

          if (row >= 0 && row < 3 && col >= 0 && col < 3) { // 确保位置有效
              const cellIndex = row * 3 + col;
              const cell = board.children[cellIndex];

              if (cell) {
                // 检查单元格是否已被占用
                if (cell.dataset.fighterId) {
                    console.warn(`Cell at [${row}, ${col}] is already occupied by fighter ${cell.dataset.fighterId}. Skipping fighter ${fighter.name}.`);
                } else {
                    cell.innerHTML = `<span>${fighter.name}</span><span class="hp">${fighter.hp}</span>`;
                    cell.dataset.fighterId = fighter.id;
                    cell.addEventListener('click', () => showFighterDetails(fighter));
                }
              } else {
                  console.error(`Cell at index ${cellIndex} not found for team ${team}.`);
              }
          } else {
              console.warn(`Calculated invalid board position [${row}, ${col}] for fighter ${fighter.name} with position ${fighter.position}.`);
          }
      });
    }


