    function parseFighters(data, team) {
      const fighters = [];
      const regex = /<战斗员\d+>[\s\n]*\[姓名[:：]\s*([^\]]*)\][\s\n]*\[HP[:：]\s*([^\]]*)\][\s\n]*\[位置[:：]\s*([^\]]*)\][\s\n]*\[当前姿态[:：]\s*([^\]]*)\][\s\n]*\[图示[:：]\s*([^\]]*?)\s*\][\s\n]*\[语言[:：]\s*([^\]]*)\][\s\n]*\[所有姿态[:：]\s*([^\]]*)\][\s\n]*<\/战斗员\d+>/g;
      let match;
      let index = 0;
      while ((match = regex.exec(data)) !== null) {
        fighters.push({
          id: `${team}-${index++}`, name: match[1].trim(), hp: match[2].trim(),
          position: match[3].trim(), currentStance: match[4].trim(),
          imageKeyword: match[5].trim(), speech: match[6].trim(),
          allStances: match[7].split(/\s+/).filter(s => s.trim() !== '')
        });
      }
      return fighters;
    }

    function initBattleBoard(team, fighters) {
      const board = document.getElementById(`team-${team}-board`);
      board.innerHTML = '';
      const positionMap = team === 'a' ? { '后': 0, '中': 1, '前': 2 } : { '前': 0, '中': 1, '后': 2 };
      for (let i = 0; i < 9; i++) {
        const cell = document.createElement('div');
        cell.className = `battle-cell team-${team}`;
        board.appendChild(cell);
      }
      fighters.forEach(fighter => {
          const posMatch = fighter.position.match(/(前|中|后)(\d)/);
          if (!posMatch) return;
          const [, pos, num] = posMatch;
          const col = positionMap[pos];
          const row = parseInt(num) - 1;
          if (row >= 0 && row < 3 && col >= 0 && col < 3) {
              const cell = board.children[row * 3 + col];
              if (cell && !cell.dataset.fighterId) {
                cell.innerHTML = `<span>${fighter.name}</span><span class="hp">${fighter.hp}</span>`;
                cell.dataset.fighterId = fighter.id;
                cell.addEventListener('click', () => showFighterDetails(fighter));
              }
          }
      });
    }

    function parseDanmaku(data) {
        const danmakuList = [];
        const regex = /\[([^:\]]+)[:：]([^\]]+)\]/g;
        let match;
        while ((match = regex.exec(data)) !== null) {
            danmakuList.push({ name: match[1].trim(), text: match[2].trim() });
        }
        return danmakuList;
    }

    function getRandomColor() {
        const hue = Math.floor(Math.random() * 360);
        return `hsl(${hue}, 90%, 75%)`;
    }

    // --- 妈妈修改的核心部分在这里 ---
    let danmakuTimeout; // 使用 Timeout 来控制，更灵活
    function showDanmaku(danmakuList) {
        const container = document.getElementById('danmaku-container');
        if (!container || danmakuList.length === 0) return;
        let index = 0;

        function releaseNextDanmaku() {
            // 如果一轮弹幕已经发完
            if (index >= danmakuList.length) {
                // 设置一个长延迟，然后重新开始
                danmakuTimeout = setTimeout(() => {
                    index = 0; // 重置索引，开始新的一轮
                    releaseNextDanmaku();
                }, danmakuConfig.loopDelay);
                return; // 等待延迟结束
            }

            // 发射当前的弹幕
            const danmaku = danmakuList[index];
            const item = document.createElement('div');
            item.className = 'danmaku-item';
            item.innerHTML = `<strong>${danmaku.name}:</strong> ${danmaku.text}`;
            item.style.color = getRandomColor();
            const duration = Math.random() * 6 + 10;
            item.style.top = `${Math.random() * 80 + 5}%`;
            const animationName = `danmaku-scroll-${Date.now()}-${index}`;
            const keyframesRule = `@keyframes ${animationName} { from { transform: translateX(${container.offsetWidth}px); } to { transform: translateX(-100%); } }`;
            if (document.styleSheets.length === 0) {
                const style = document.createElement('style');
                document.head.appendChild(style);
            }
            document.styleSheets[0].insertRule(keyframesRule, document.styleSheets[0].cssRules.length);
            item.style.animation = `${animationName} ${duration}s linear`;
            item.addEventListener('animationend', () => item.remove());
            container.appendChild(item);
            index++;

            // 计算下一条弹幕的随机间隔时间
            const nextInterval = Math.random() * (danmakuConfig.maxInterval - danmakuConfig.minInterval) + danmakuConfig.minInterval;
            // 设置定时器，在指定间隔后发射下一条弹幕
            danmakuTimeout = setTimeout(releaseNextDanmaku, nextInterval);
        }

        clearTimeout(danmakuTimeout); // 清除可能存在的旧定时器
        releaseNextDanmaku(); // 开始发射流程
    }

    const overlay = document.getElementById('overlay');
    const fighterDetailsPopup = document.getElementById('fighter-details');
    const allDanmakuPopup = document.getElementById('all-danmaku-modal');
