      const fighterImageTag = document.getElementById('fighter-image-tag');
      if (imageUrl) {
        fighterImageTag.src = imageUrl;
        fighterImageTag.style.display = 'block';
        fighterImageTag.onclick = () => showImageModal(imageUrl);
      } else {
        fighterImageTag.src = '';
        fighterImageTag.style.display = 'none';
        fighterImageTag.onclick = null;
      }
      const stancesList = document.getElementById('stances-list');
      stancesList.innerHTML = fighter.allStances.length ? '' : '<span>无其他姿态</span>';
      fighter.allStances.forEach(stance => {
        const span = document.createElement('span');
        span.textContent = stance;
        stancesList.appendChild(span);
      });
      overlay.classList.add('show');
      fighterDetailsPopup.classList.add('show');
    }

    function closeAllPopups() {
      overlay.classList.remove('show');
      fighterDetailsPopup.classList.remove('show');
      allDanmakuPopup.classList.remove('show');
      imageModal.classList.remove('show');
    }

    function showImageModal(imageUrl) {
        if (imageUrl) {
            document.getElementById('modal-image').src = imageUrl;
            imageModal.classList.add('show');
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
      try {
          const aFightersData = `$3`;
          const bFightersData = `$6`;
          const danmakuData = `$7`;
          const aFighters = parseFighters(aFightersData, 'a');
          const bFighters = parseFighters(bFightersData, 'b');
          const danmakuList = parseDanmaku(danmakuData);

          initBattleBoard('a', aFighters);
          initBattleBoard('b', bFighters);
          if (danmakuList.length > 0) showDanmaku(danmakuList);

          const toggleDanmakuBtn = document.getElementById('toggle-danmaku-btn');
          const showAllDanmakuBtn = document.getElementById('show-all-danmaku-btn');
          const danmakuContainer = document.getElementById('danmaku-container');
          let danmakuVisible = true;

          toggleDanmakuBtn.addEventListener('click', () => {
              danmakuVisible = !danmakuVisible;
              danmakuContainer.style.display = danmakuVisible ? 'block' : 'none';
              toggleDanmakuBtn.textContent = danmakuVisible ? '关闭弹幕' : '开启弹幕';
              if (danmakuVisible) {
                  showDanmaku(danmakuList);
              } else {
                  clearTimeout(danmakuTimeout); // 确保关闭时清除定时器
                  danmakuContainer.innerHTML = '';
              }
          });

          showAllDanmakuBtn.addEventListener('click', () => {
              const listContainer = document.getElementById('danmaku-list-static');
              listContainer.innerHTML = '';
              if (danmakuList.length > 0) {
                  danmakuList.forEach(d => {
                      const p = document.createElement('p');
                      p.innerHTML = `<strong>${d.name}:</strong> ${d.text}`;
                      listContainer.appendChild(p);
                  });
              } else {
                  listContainer.innerHTML = '<p>当前没有弹幕。</p>';
              }
              overlay.classList.add('show');
              allDanmakuPopup.classList.add('show');
          });

          document.getElementById('close-details-btn').addEventListener('click', closeAllPopups);
          document.getElementById('close-all-danmaku-btn').addEventListener('click', closeAllPopups);
          document.getElementById('modal-close-btn').addEventListener('click', closeAllPopups);
          overlay.addEventListener('click', closeAllPopups);
          imageModal.addEventListener('click', (e) => { if (e.target === imageModal) closeAllPopups(); });

      } catch (error) {
          console.error("Error initializing battle board:", error);
      }
    });
</script>

