                        <div class="section-body"></div>
                    </div>
                    <div id="official-releases" class="section">
                        <h2 class="section-title">权威发布</h2>
                        <div class="section-body"></div>
                    </div>
                </main>
            </div>
            <!-- 反面 -->
            <div class="newspaper-page back">
                <main>
                    <div id="opinions" class="section">
                        <h2 class="section-title">今日观点</h2>
                        <div class="section-body"></div>
                    </div>
                    <div id="economy" class="section">
                        <h2 class="section-title">经济版</h2>
                        <div class="section-body"></div>
                    </div>
                    <div id="life" class="section">
                        <h2 class="section-title">生活版</h2>
                        <div class="section-body"></div>
                    </div>
                    <div id="commissions" class="section">
                        <h2 class="section-title">委托广告</h2>
                        <div class="section-body"></div>
                    </div>
                </main>
            </div>
