    /* 响应式设计 */
    @media (max-width: 600px) {
      body { padding: 5px; }
      .top-bar { flex-direction: column; align-items: flex-start; gap: 5px; padding: 10px; }
      .actions-bar { justify-content: center; }
      .placeholder-buttons { margin-left: 0; margin-top: 10px; width: 100%; justify-content: space-around; }
      .modal-content { width: 95%; }
      textarea.input-field { min-height: 100px; }
