<body>
  <div class="info-container">
    <div class="top-bar">
      <div class="top-bar-item"><span class="icon">🕒</span><span id="time-val">$1</span></div>
      <div class="top-bar-item"><span class="icon">☁️</span><span id="weather-val">$2</span></div>
      <div class="top-bar-item"><span class="icon">📍</span><span id="location-val">$3</span></div>
    </div>
    <div class="actions-bar">
      <button class="action-button" data-title="剧情概括" data-content="$4">剧情概括</button>
      <button class="action-button secondary" data-title="在场角色" data-content="$5">在场角色</button>
      <div class="placeholder-buttons">
        <div class="placeholder-item">
          <button class="placeholder-button pb-1" id="btn-open-combatants"></button>
          <span class="placeholder-label">我的战斗员</span>
        </div>
        <div class="placeholder-item">
          <button class="placeholder-button pb-2" onclick="setInputText('看看新闻')"></button>
          <span class="placeholder-label">看看新闻</span>
        </div>
        <div class="placeholder-item">
          <button class="placeholder-button pb-3" onclick="setInputText('使用洞视之眼查看 信息')"></button>
          <span class="placeholder-label">洞视之眼</span>
        </div>
        <div class="placeholder-item">
          <button class="placeholder-button pb-4" onclick="setInputText('隐奸NTL{请根据当前剧情生成隐奸NTL剧情，剧情应符合逻辑与角色设定}')"></button>
          <span class="placeholder-label">隐奸NTL</span>
        </div>
        <div class="placeholder-item">
          <button class="placeholder-button pb-5"></button>
          <span class="placeholder-label">空白按钮5</span>
        </div>
      </div>
    </div>
  </div>

  <div id="info-modal" class="modal-overlay">
    <div class="modal-content">
      <button class="modal-close-btn">&times;</button>
      <div id="modal-unified-content" class="modal-unified-content">
        <!-- 内容将由JS动态注入 -->
      </div>
    </div>
  </div>

  <div id="notification-container"></div>

  <script>
    function setInputText(text) {
      if (typeof triggerSlash === 'function') {
        triggerSlash(`/setinput ${text}`);
      } else {
        console.error('Error: triggerSlash function is not defined.');
        alert('此功能需要脚本扩展支持。');
      }
    }

    document.addEventListener('DOMContentLoaded', function() {
      const container = document.querySelector('.info-container');
      const modalOverlay = document.getElementById('info-modal');
      const modalContent = modalOverlay.querySelector('.modal-content');
      const modalUnifiedContent = document.getElementById('modal-unified-content');
      const modalCloseBtn = modalOverlay.querySelector('.modal-close-btn');
      let originalBodyHeight = '';

      function openModal(title, content) {
        let bodyHtml = '';
        if (content && content.trim()) {
            bodyHtml = /<[a-z][\s\S]*>/i.test(content) ? content : content.replace(/\n/g, '<br>');
        } else {
            bodyHtml = '<p class="info-message">暂无信息</p>';
        }

        modalUnifiedContent.innerHTML = `
            <div class="modal-title-area">${title}</div>
            <div class="modal-body-area">${bodyHtml}</div>`;
        modalOverlay.classList.add('active');
        adjustHeight();
      }

      function closeModal() {
        modalOverlay.classList.remove('active');
        if (originalBodyHeight) {
            document.body.style.height = originalBodyHeight;
            originalBodyHeight = '';
        }
      }

      function adjustHeight() {
          setTimeout(() => {
            if (!modalOverlay.classList.contains('active')) return;
            if (!originalBodyHeight) {
              originalBodyHeight = document.body.style.height || 'auto';
            }
            const requiredBodyHeight = modalContent.scrollHeight + 40;
            const finalHeight = Math.max(container.scrollHeight, requiredBodyHeight);
            document.body.style.height = finalHeight + 'px';
          }, 50);
      }

      document.querySelectorAll('.action-button[data-title]').forEach(button => {
        button.addEventListener('click', function() {
          openModal(this.getAttribute('data-title'), this.getAttribute('data-content'));
        });
      });

      modalCloseBtn.addEventListener('click', closeModal);
      modalOverlay.addEventListener('click', e => { if (e.target === modalOverlay) closeModal(); });
      document.addEventListener('keydown', e => { if (e.key === 'Escape' && modalOverlay.classList.contains('active')) closeModal(); });

      // --- 战斗员面板逻辑 ---
      const CONFIG_KEY = 'combatPanelConfig_v5.1';
      const combatantState = {
        config: { lorebookName: '', entryComment: '' },
        currentEntry: null
      };

      const showNotification = (message, type = 'info') => {
        const container = document.getElementById('notification-container');
        const toast = document.createElement('div');
        toast.className = `toast ${type}`;
        toast.textContent = message;
        container.appendChild(toast);
        setTimeout(() => {
            toast.style.opacity = '0';
            setTimeout(() => toast.remove(), 300);
        }, 3000);
      };

      const loadCombatantConfig = () => {
          const savedConfig = localStorage.getItem(CONFIG_KEY);
          if (savedConfig) {
              try {
                  combatantState.config = JSON.parse(savedConfig);
              } catch (e) {
                  console.error("解析战斗员配置失败:", e);
                  localStorage.removeItem(CONFIG_KEY);
              }
          }
      };

      const showCombatantModal = async (view, params = {}) => {
          if (!modalOverlay.classList.contains('active')) {
              modalOverlay.classList.add('active');
          }
          modalUnifiedContent.innerHTML = '<div class="loader"></div>';

          try {
              let html = '';
              if (view === 'config') {
                  html = `
                      <div class="modal-title-area">配置目标</div>
                      <div class="modal-body-area">
                          <div class="form-row">
                              <label for="lorebook">世界书名称:</label>
                              <input type="text" id="lorebook" class="input-field" value="${combatantState.config.lorebookName || ''}" placeholder="输入世界书名称...">
                          </div>
                          <div class="form-row">
                              <label for="comment">条目注释 (用于定位列表):</label>
                              <input type="text" id="comment" class="input-field" value="${combatantState.config.entryComment || ''}" placeholder="战斗员列表总条目的注释...">
                          </div>
                      </div>
                      <div class="modal-footer-area">
                          <button id="save-config" class="action-button">保存并刷新列表</button>
                      </div>`;
              } else if (view === 'combatants') {
                  if (!combatantState.config.lorebookName || !combatantState.config.entryComment) {
                      showNotification('请先配置世界书和战斗员列表条目注释。', 'info');
                      return showCombatantModal('config');
                  }
                  const mainListEntries = await getLorebookEntries(combatantState.config.lorebookName, { filter: { comment: combatantState.config.entryComment }, fields: ['uid', 'content'] });
                  if (!mainListEntries || mainListEntries.length === 0) throw new Error(`在世界书 "${combatantState.config.lorebookName}" 中未找到注释为 "${combatantState.config.entryComment}" 的条目。`);
                  combatantState.currentEntry = mainListEntries[0];
                  const names = Array.from(combatantState.currentEntry.content.matchAll(/\[([^\]]+)\]/g), m => m[1]);
                  const bodyContent = names.length
                      ? `<div class="combatant-buttons-container">${names.map(name => `<button class="name-button">${name}</button>`).join('')}</div>`
                      : '<p class="info-message">当前列表为空。您可以点击“编辑列表”进行添加。</p>';
                  html = `
                      <div class="modal-title-area">
                          <span>战斗员列表</span>
                          <div class="modal-header-actions">
                              <button id="btn-open-config" class="action-button secondary">配置</button>
                              <button id="btn-open-editor" class="action-button">编辑列表</button>
                          </div>
                      </div>
                      <div class="modal-body-area">${bodyContent}</div>`;
              } else if (view === 'editor') {
                  if (!combatantState.currentEntry) throw new Error('无法找到战斗员列表缓存。');
                  html = `
                      <div class="modal-title-area">编辑战斗员列表</div>
                      <div class="modal-body-area">
                          <textarea id="content-area" class="input-field">${combatantState.currentEntry.content}</textarea>
                      </div>
                      <div class="modal-footer-area">
                          <button id="save-entry" class="action-button">确认修改</button>
                      </div>`;
              } else if (view === 'search') {
                  const entries = await getLorebookEntries(combatantState.config.lorebookName, { filter: { comment: params.name }, fields: ['comment', 'content'] });
                  const bodyContent = entries.length
                      ? entries.map(e => `<div class="result-item"><h3>${e.comment || '无标题'}</h3><p>${e.content.replace(/\n/g, '<br>')}</p></div>`).join('')
                      : `<p class="info-message">未找到注释为 "${params.name}" 的详细条目。</p>`;
                  html = `
                      <div class="modal-title-area">“${params.name}”的档案</div>
                      <div class="modal-body-area">${bodyContent}</div>`;
              }
              modalUnifiedContent.innerHTML = html;
          } catch (error) {
modalUnifiedContent.innerHTML = `
    <div class="modal-title-area">操作错误</div>
    <div class="modal-body-area">
        <p class="info-message">${error.message}</p>
    </div>
    <div class="modal-footer-area">
        <button id="btn-error-back-to-config" class="action-button secondary">返回配置</button>
    </div>`;
              showNotification(`错误: ${error.message}`, 'error');
          } finally {
              adjustHeight();
          }
      };

      // --- 事件委托 ---
      modalUnifiedContent.addEventListener('click', async (e) => {
          const target = e.target;
          if (target.id === 'save-config') {
              const lorebook = document.getElementById('lorebook').value.trim();
              const comment = document.getElementById('comment').value.trim();
              if (!lorebook || !comment) return showNotification('世界书名称和条目注释不能为空！', 'error');
              combatantState.config = { lorebookName: lorebook, entryComment: comment };
              localStorage.setItem(CONFIG_KEY, JSON.stringify(combatantState.config));
              showNotification('配置已保存', 'success');
              showCombatantModal('combatants');
          } else if (target.id === 'btn-open-config') {
              showCombatantModal('config');
          } else if (target.id === 'btn-open-editor') {
              if (!combatantState.currentEntry) return showNotification('请先加载战斗员列表。', 'error');
              showCombatantModal('editor');
          } else if (target.classList.contains('name-button')) {
              showCombatantModal('search', { name: target.textContent });
          } else if (target.id === 'save-entry') {
              target.disabled = true;
              target.textContent = '保存中...';
              try {
                  const newContent = document.getElementById('content-area').value;
                  await setLorebookEntries(combatantState.config.lorebookName, [{ uid: combatantState.currentEntry.uid, content: newContent }]);
                  combatantState.currentEntry.content = newContent;
                  showNotification('战斗员列表修改成功！', 'success');
                  showCombatantModal('combatants');
              } catch (err) {
                  showNotification(`保存失败: ${err.message}`, 'error');
                  target.disabled = false;
                  target.textContent = '确认修改';
              }
          }else if (target.id === 'btn-error-back-to-config') {
             showCombatantModal('config'); // 调用函数切换到配置视图
          }

      });

      loadCombatantConfig();
      document.getElementById('btn-open-combatants').onclick = () => showCombatantModal('combatants');
    });
  </script>
</body>
</html>
